    if (strstart(devname, "host:", &p)) {

        dev = usb_host_device_open(p);

    } else if (!strcmp(devname, "mouse")) {

        dev = usb_mouse_init();

    } else if (!strcmp(devname, "tablet")) {

        dev = usb_tablet_init();

    } else if (!strcmp(devname, "keyboard")) {

        dev = usb_keyboard_init();

