                dev->handle_destroy(dev);

                return -1;

            }

        }

    } else if (!strcmp(devname, "wacom-tablet")) {

        dev = usb_wacom_init();

    } else if (strstart(devname, "serial:", &p)) {

        dev = usb_serial_init(p);

#ifdef CONFIG_BRLAPI

    } else if (!strcmp(devname, "braille")) {

        dev = usb_baum_init();

