    }



    index = cryptodev_builtin_get_unused_session_index(builtin);

    if (index < 0) {

        error_setg(errp, "Total number of sessions created exceeds %u",

                  MAX_NUM_SESSIONS);

        return -1;

    }



    switch (sess_info->cipher_alg) {

